<template><section class="team-role-review"><div class="admin-team-filters"><label>角色申请状态<select v-model="status"><option value="">全部状态</option><option value="pending">待审核</option><option value="approved">已通过</option><option value="returned">已退回</option><option value="withdrawn">已撤回</option></select></label><button :disabled="busy" @click="page=1;load()">查询角色申请</button></div><p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p>
  <div class="team-table-wrap"><table><thead><tr><th>球队</th><th>赛事</th><th>角色</th><th>新任人选</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="v in items" :key="v.id"><td>{{ v.team_name }}</td><td>{{ v.league_type }}</td><td>{{ v.role==='manager'?'负责人':'场上队长' }}</td><td>{{ v.new_name }}</td><td>{{ labels[v.status] }}</td><td><button :disabled="busy" @click="open(v.id)">审核角色变更</button></td></tr><tr v-if="!items.length"><td colspan="6">暂无角色变更申请</td></tr></tbody></table></div><div class="team-pagination"><span>共 {{ pagination.total }} 份 · 第 {{ page }} 页</span><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><button :disabled="busy||page>=pagination.total_pages" @click="page++;load()">下一页</button></div>
  <section v-if="detail" class="team-review-detail role-review-detail"><div class="admin-team-heading"><h2>{{ detail.team.name }} · {{ detail.request.role==='manager'?'负责人':'场上队长' }}变更</h2><button :disabled="busy" @click="open(detail.request.id)">刷新角色详情</button></div><div class="admin-team-profile"><div><h3>原任人选</h3><p>{{ detail.old.name }} · {{ detail.old.student_id }}</p></div><div><h3>新任人选</h3><p>{{ detail.next.name }} · {{ detail.next.student_id }}</p><p>{{ detail.next.college }} · {{ detail.next.is_active?'账号启用':'账号停用' }}</p><p v-if="detail.request.role==='captain'">{{ detail.is_current_member?'在当前有效名单中':'不在当前有效名单中' }} · {{ detail.qualification_status==='approved'?'学籍已通过':'学籍资格未通过' }}</p></div></div><p>状态：{{ labels[detail.request.status] }}{{ detail.request.reason?' · '+detail.request.reason:'' }}</p>
    <div v-draft="{ value: reason }" class="role-review-controls" v-if="detail.request.status==='pending'&&detail.team.is_active&&!detail.team.ended"><label>角色审核说明／退回理由<textarea v-model="reason" rows="3" maxlength="500" :disabled="busy"></textarea></label><p class="help">通过后角色和管理权限立即生效，历史名单及比赛记录保留。退回必须填写理由。</p><div class="admin-team-actions"><button class="primary" :disabled="busy" @click="review('approve')">通过角色变更</button><button :disabled="busy" @click="review('return')">退回角色变更</button></div></div>
    <details class="admin-team-history" open><summary>角色变更记录</summary><ol><li v-for="e in detail.events" :key="e.id"><strong>{{ operations[e.operation] }}</strong> · {{ time(e.created_at) }}<p>{{ e.reason }}</p><p v-if="e.after_snapshot.profile_snapshot">人选快照：{{ e.after_snapshot.profile_snapshot.name }} / {{ e.after_snapshot.profile_snapshot.student_id }} / {{ e.after_snapshot.profile_snapshot.college }}</p></li></ol></details>
  </section></section></template>
<script setup>
import { ref,watch } from 'vue'
import { confirmDraftLeave } from '../../../shared-ui/interaction.js'
import api from '../api/http'
const props=defineProps({seasonId:String}),status=ref('pending'),page=ref(1),items=ref([]),pagination=ref({total:0,total_pages:0}),busy=ref(false),error=ref(''),success=ref(''),detail=ref(null),reason=ref('');let sequence=0,detailSequence=0
const labels={pending:'待审核',approved:'已通过',returned:'已退回',withdrawn:'已撤回'},operations={submitted:'提交申请',approved:'审核通过',returned:'管理员退回',withdrawn:'撤回申请'}
const time=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'
const fail=e=>error.value=e.response?.data?.message||'操作失败，请重试'
async function load(){const n=++sequence;try{const r=await api.get('/player-admin/role-changes',{params:{season_id:props.seasonId||undefined,status:status.value,page:page.value}});if(n===sequence){items.value=r.data.items;pagination.value=r.data.pagination}}catch(e){if(n===sequence)fail(e)}}
async function open(id){if(!confirmDraftLeave(document.querySelector('.role-review-controls')))return;const n=++detailSequence;error.value='';success.value='';detail.value=null;try{const r=await api.get('/player-admin/role-changes/'+id);if(n===detailSequence){detail.value=r.data;reason.value=''}}catch(e){if(n===detailSequence)fail(e)}}
async function review(action){busy.value=true;error.value='';success.value='';try{const r=await api.post(`/player-admin/role-changes/${detail.value.request.id}/${action}`,{reason:reason.value,review_token:detail.value.review_token},{headers:{'If-Match':String(detail.value.request.revision)}});detail.value=r.data;reason.value='';success.value=action==='approve'?'角色变更已通过，权限立即生效。':'角色申请已退回。';await load()}catch(e){fail(e)}finally{busy.value=false}}
watch(()=>props.seasonId,()=>{page.value=1;detailSequence++;detail.value=null;load()},{immediate:true})
</script>
